insert into public.automations ("id", "name", "description", "trigger", "conditions", "actions", "active", "run_count", "last_run_at") values ('7abf0e62-1f6f-4caa-a16f-b75e63f0301e', 'Notify sales team of new leads', 'When a new lead is created, notify the sales team.', 'lead.created', '[]'::jsonb, '[{"type":"notify","params":{"roles":"owner,sales_rep,office_manager","title":"New lead: {{title}}","body":"{{customer}} · {{source}}"}}]'::jsonb, true, 0, null);
insert into public.automations ("id", "name", "description", "trigger", "conditions", "actions", "active", "run_count", "last_run_at") values ('00ffb6da-5469-4b30-8a14-253cd9433847', 'Estimate follow-up reminder', 'When an estimate is sent, schedule a follow-up task in 3 days.', 'estimate.sent', '[]'::jsonb, '[{"type":"schedule_follow_up","params":{"days":3,"title":"Follow up on {{number}} with {{customer}}"}}]'::jsonb, true, 0, null);
insert into public.automations ("id", "name", "description", "trigger", "conditions", "actions", "active", "run_count", "last_run_at") values ('c311cf9b-112c-474d-9826-d91b825b3d5f', 'Create project from approved estimate', 'When an estimate is approved, automatically create the project and mark the lead won.', 'estimate.approved', '[]'::jsonb, '[{"type":"create_project","params":{}},{"type":"notify","params":{"roles":"owner,project_manager,office_manager","title":"Estimate approved: {{number}}","body":"{{customer}} · {{total}}"}}]'::jsonb, true, 0, null);
insert into public.automations ("id", "name", "description", "trigger", "conditions", "actions", "active", "run_count", "last_run_at") values ('1eb41f6e-0d6f-4c28-905a-06b4e71ae3c3', 'Notify PM when contract signed', 'When a contract is signed, notify the project manager.', 'contract.signed', '[]'::jsonb, '[{"type":"notify","params":{"roles":"project_manager,owner","title":"Contract signed: {{name}}","body":"Ready for deposit invoice"}}]'::jsonb, true, 0, null);
insert into public.automations ("id", "name", "description", "trigger", "conditions", "actions", "active", "run_count", "last_run_at") values ('4c901e73-3237-4050-a512-ddeee5db3066', 'Deposit received → advance project', 'When a deposit is received, move the project to Deposit Received.', 'deposit.received', '[]'::jsonb, '[{"type":"set_project_stage","params":{"stage":"Deposit Received"}},{"type":"notify","params":{"roles":"project_manager,office_manager","title":"Deposit received: {{project}}","body":"{{amount}} via {{method}}"}}]'::jsonb, true, 0, null);
insert into public.automations ("id", "name", "description", "trigger", "conditions", "actions", "active", "run_count", "last_run_at") values ('fe5e00bd-7da2-4940-9a59-4b701fc6d3e8', 'Materials ordered → update timeline', 'When a purchase order is placed for a project, set the project to Materials Ordered.', 'po.ordered', '[]'::jsonb, '[{"type":"set_project_stage","params":{"stage":"Materials Ordered","only_if_before":true}},{"type":"log_activity","params":{"subject":"Materials ordered ({{number}})"}}]'::jsonb, true, 0, null);
insert into public.automations ("id", "name", "description", "trigger", "conditions", "actions", "active", "run_count", "last_run_at") values ('0888af0b-b0d0-4bf2-8998-24abe855fa79', 'Materials received → update project', 'When a purchase order is fully received, set the project to Materials Delivered.', 'po.received', '[]'::jsonb, '[{"type":"set_project_stage","params":{"stage":"Materials Delivered","only_if_before":true}}]'::jsonb, true, 0, null);
insert into public.automations ("id", "name", "description", "trigger", "conditions", "actions", "active", "run_count", "last_run_at") values ('186beddd-5d48-4dc1-81cb-b038189953db', 'Installation reminder to customer', 'Before a scheduled installation, notify the customer (email/SMS integration ready).', 'event.upcoming_installation', '[]'::jsonb, '[{"type":"send_email","params":{"to":"customer","subject":"Your installation is scheduled for {{date}}","body":"Hi {{customer}}, our crew arrives {{date}}."}},{"type":"log_activity","params":{"subject":"Installation reminder sent for {{date}}"}}]'::jsonb, true, 0, null);
insert into public.automations ("id", "name", "description", "trigger", "conditions", "actions", "active", "run_count", "last_run_at") values ('784d7772-0f23-4808-8937-6a2e31fb6f0a', 'Final invoice reminder on completion', 'When a project is completed, create the final invoice reminder.', 'project.completed', '[]'::jsonb, '[{"type":"create_final_invoice","params":{}},{"type":"notify","params":{"roles":"office_manager,owner","title":"Final invoice ready: {{name}}","body":"Project completed — send the final invoice."}}]'::jsonb, true, 0, null);
insert into public.automations ("id", "name", "description", "trigger", "conditions", "actions", "active", "run_count", "last_run_at") values ('c1a3ed90-6857-45f6-8703-9afb5f5ce483', 'Overdue invoice alert', 'When an invoice becomes overdue, notify the office.', 'invoice.overdue', '[]'::jsonb, '[{"type":"notify","params":{"roles":"office_manager,owner","title":"Invoice overdue: {{number}}","body":"{{customer}} · balance {{balance}}","kind":"danger"}}]'::jsonb, true, 0, null);
insert into public.automations ("id", "name", "description", "trigger", "conditions", "actions", "active", "run_count", "last_run_at") values ('ac92a0b8-ab62-4f5e-8f8e-94024fe3fc1c', 'Change order approved', 'When a customer approves a change order, notify the PM.', 'change_order.approved', '[]'::jsonb, '[{"type":"notify","params":{"roles":"project_manager,owner","title":"Change order approved: {{number}}","body":"{{amount}} added to contract"}}]'::jsonb, true, 0, null);
insert into public.automations ("id", "name", "description", "trigger", "conditions", "actions", "active", "run_count", "last_run_at") values ('fc499083-d98e-4bd2-981c-c44c671ce957', 'Portal message received', 'When a customer sends a message in the portal, notify the office.', 'portal.message', '[]'::jsonb, '[{"type":"notify","params":{"roles":"office_manager,project_manager,owner","title":"New message from {{customer}}","body":"{{body}}"}}]'::jsonb, true, 0, null);
